/* eslint-disable eqeqeq */
import { Component, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AlertController, IonContent, LoadingController, ToastController } from '@ionic/angular';
import { Subscription } from 'rxjs';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { CamTimingResult, timingFromEvents, timingFromSpecs } from './cam-timing.util';

@Component({
  selector: 'app-cam-timing',
  templateUrl: './cam-timing.component.html',
  styleUrls: ['./cam-timing.component.scss'],
})
export class CamTimingPage implements OnInit, OnDestroy {

  @ViewChild(IonContent) content: IonContent;

  isCheck = true;
  queryText = '';
  showSearchbar = false;
  activeMode: 'specs' | 'events' = 'specs';
  measurementBasis: 'advertised' | '050' = 'advertised';
  form: FormGroup;
  form2: FormGroup;
  result: CamTimingResult | null = null;
  resultWarning = '';
  private readonly subscriptions = new Subscription();

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.check();
  }

  ngOnInit(): void {
    this.form = this.fb.group({
      intakeDuration: [220, [Validators.required, Validators.min(150), Validators.max(360)]],
      exhaustDuration: [220, [Validators.required, Validators.min(150), Validators.max(360)]],
      lobeSeparation: [110, [Validators.required, Validators.min(70), Validators.max(145)]],
      advance: [4, [Validators.required, Validators.min(-30), Validators.max(30)]],
    });
    this.form2 = this.fb.group({
      intakeOpenBtdc: [4, [Validators.required, Validators.min(-180), Validators.max(180)]],
      intakeCloseAbdc: [36, [Validators.required, Validators.min(-180), Validators.max(180)]],
      exhaustOpenBbdc: [44, [Validators.required, Validators.min(-180), Validators.max(180)]],
      exhaustCloseAtdc: [-4, [Validators.required, Validators.min(-180), Validators.max(180)]],
    });
    this.subscriptions.add(this.form.valueChanges.subscribe(() => {
      if (this.activeMode === 'specs') { this.recalculate(); }
    }));
    this.subscriptions.add(this.form2.valueChanges.subscribe(() => {
      if (this.activeMode === 'events') { this.recalculate(); }
    }));
    this.recalculate();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  selectMode(mode: 'specs' | 'events'): void {
    this.activeMode = mode;
    this.recalculate();
  }

  recalculate(): void {
    const active = this.activeMode === 'specs' ? this.form : this.form2;
    if (!active || active.invalid) {
      this.result = null;
      this.resultWarning = 'مقادیر را در بازهٔ مجاز وارد کنید.';
      return;
    }
    const values = active.getRawValue();
    const numbers = Object.keys(values).map(key => Number(values[key]));
    if (numbers.some(value => !Number.isFinite(value))) {
      this.result = null;
      this.resultWarning = 'همهٔ ورودی‌ها باید عدد معتبر باشند.';
      return;
    }

    const result = this.activeMode === 'specs'
      ? timingFromSpecs({
          intakeDuration: Number(values.intakeDuration),
          exhaustDuration: Number(values.exhaustDuration),
          lobeSeparation: Number(values.lobeSeparation),
          advance: Number(values.advance),
        })
      : timingFromEvents({
          intakeOpenBtdc: Number(values.intakeOpenBtdc),
          intakeCloseAbdc: Number(values.intakeCloseAbdc),
          exhaustOpenBbdc: Number(values.exhaustOpenBbdc),
          exhaustCloseAtdc: Number(values.exhaustCloseAtdc),
        });

    if (result.intakeDuration <= 0 || result.exhaustDuration <= 0 ||
        result.intakeCenterline <= 0 || result.exhaustCenterline <= 0) {
      this.result = null;
      this.resultWarning = 'ترکیب رویدادها دوریشن یا سنترلاین فیزیکی معتبر نمی‌سازد.';
      return;
    }

    this.result = result;
    if (result.intakeDuration < 150 || result.exhaustDuration < 150 ||
        result.intakeDuration > 360 || result.exhaustDuration > 360) {
      this.resultWarning = 'دوریشن حاصل خارج از بازهٔ رایج است؛ علامت و مبنای رویدادها را بررسی کنید.';
    } else if (result.lobeSeparation < 85 || result.lobeSeparation > 125) {
      this.resultWarning = 'LSA حاصل غیرمعمول است؛ زاویه‌ها و مبنای اندازه‌گیری را دوباره کنترل کنید.';
    } else if (result.overlap < 0) {
      this.resultWarning = 'همپوشانی منفی یعنی اطراف TDC بازه‌ای وجود دارد که هیچ‌یک از دو سوپاپ باز نیست.';
    } else {
      this.resultWarning = '';
    }
  }

  onReset(): void {
    if (this.activeMode === 'specs') {
      this.form.reset({ intakeDuration: 220, exhaustDuration: 220, lobeSeparation: 110, advance: 4 });
    } else {
      this.form2.reset({ intakeOpenBtdc: 4, intakeCloseAbdc: 36, exhaustOpenBbdc: 44, exhaustCloseAtdc: -4 });
    }
  }

  useResultInOtherMode(): void {
    if (!this.result) { return; }
    if (this.activeMode === 'specs') {
      this.form2.patchValue({
        intakeOpenBtdc: this.result.intakeOpenBtdc,
        intakeCloseAbdc: this.result.intakeCloseAbdc,
        exhaustOpenBbdc: this.result.exhaustOpenBbdc,
        exhaustCloseAtdc: this.result.exhaustCloseAtdc,
      }, { emitEvent: false });
      this.selectMode('events');
    } else {
      this.form.patchValue({
        intakeDuration: this.result.intakeDuration,
        exhaustDuration: this.result.exhaustDuration,
        lobeSeparation: this.result.lobeSeparation,
        advance: this.result.advance,
      }, { emitEvent: false });
      this.selectMode('specs');
    }
  }

  eventLabel(value: number, positive: string, negative: string, zero: string): string {
    if (value === 0) { return '0° ' + zero; }
    const absolute = Math.abs(value).toFixed(1).replace(/\.0$/, '');
    return absolute + '° ' + (value > 0 ? positive : negative);
  }

  onInfo(type: string): void {
    const messages: Record<string, string> = {
      intakeDuration: 'دوریشن هوا برحسب درجهٔ میل‌لنگ، در مبنای لیفتی که انتخاب کرده‌اید. دوریشن advertised و 0.050 اینچ یکسان نیستند.',
      exhaustDuration: 'دوریشن دود را در همان مبنای اندازه‌گیری دوریشن هوا وارد کنید.',
      lobeSeparation: 'LSA میانگین سنترلاین هوای نصب‌شده و سنترلاین دود است. به‌تنهایی با جابه‌جایی میل‌سوپاپ تغییر نمی‌کند.',
      advance: 'ادونس مثبت، سنترلاین هوا را پایین‌تر می‌آورد: ICL = LSA − Advance. مقدار منفی یعنی ریتارد.',
      intakeOpenBtdc: 'بازشدن هوا قبل از TDC همپوشانی. اگر پس از TDC باز می‌شود مقدار منفی وارد کنید.',
      intakeCloseAbdc: 'بسته‌شدن هوا بعد از BDC مکش. اگر پیش از BDC بسته می‌شود مقدار منفی وارد کنید.',
      exhaustOpenBbdc: 'بازشدن دود قبل از BDC قدرت. اگر پس از BDC باز می‌شود مقدار منفی وارد کنید.',
      exhaustCloseAtdc: 'بسته‌شدن دود بعد از TDC همپوشانی. اگر پیش از TDC بسته می‌شود مقدار منفی وارد کنید.',
    };
    this.presentActiveAlertConfirm(messages[type] || 'برای این پارامتر توضیحی موجود نیست.');
  }

  async presentActiveAlertConfirm(message: string): Promise<void> {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'راهنمای پارامتر',
      message,
      buttons: ['بستن'],
    });
    await alert.present();
  }

  onCancel(): void {
    this.showSearchbar = false;
  }

  search(): void {
    if (!this.queryText?.trim()) { return; }
    this.router.navigate(['Home', 'Search'], { queryParams: { title: this.queryText } });
  }

  goTop(): void {
    this.content?.scrollToTop(300);
  }

  onNavigate(url: string): void {
    this.router.navigateByUrl(url);
  }



  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(22).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

}
